import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def clean_key(x):
    if x is None:
        return ""
    return str(x).strip()

def to_number(x):
    if isinstance(x, bool):
        return 0.0
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        s = x.strip()
        if not s:
            return 0.0
        try:
            return float(s)
        except ValueError:
            return 0.0
    return 0.0

# Header map from B2:Z2, matching the formula's MATCH range.
header_cols = {}
for col in range(2, 27):  # B through Z
    v = vws.cell(row=2, column=col).value
    if v is not None:
        key = clean_key(v)
        if key:
            header_cols[key] = col

# Fallback: if no headers were found in B:Z, scan the rest of row 2.
if not header_cols:
    for col in range(2, vws.max_column + 1):
        v = vws.cell(row=2, column=col).value
        if v is not None:
            key = clean_key(v)
            if key:
                header_cols[key] = col

results = []
for r in range(7, 11):
    key = clean_key(vws.cell(row=r, column=1).value)
    col = header_cols.get(key)

    total = 0.0
    if col is not None:
        for rr in range(3, 6):  # rows 3 through 5
            total += to_number(vws.cell(row=rr, column=col).value)

    if total == int(total):
        total = int(total)

    ws.cell(row=r, column=2).value = total
    results.append((r, key, col, total))

print("active sheet:", ws.title)
print("header_cols:", header_cols)
print("results:", results)

wb.save(OUT)
